insert into public.assessment_stimuli(code,title,content,stimulus_type,audio_script,content_hidden,max_plays) values('KLI-LST-BC-01','Campus Library Orientation','Transcript withheld during practice delivery','listening_script','Librarian: Welcome to the research library. The first floor contains the information desk, reserve materials, and group-study rooms. Quiet study areas are on the third floor. You may borrow regular books for three weeks, but reserve materials must remain in the building. To use a group room, make a reservation online. During examinations, reservations are limited to two hours so that more students have access.',true,2) on conflict(code) do update set audio_script=excluded.audio_script,content_hidden=true,max_plays=2;
insert into public.assessment_questions(test_id,prompt,options,correct_option,points,sort_order,competency,difficulty,section_id,item_type,randomize_options,stimulus_id) select t.id,'Where are the quiet study areas?','["On the first floor", "On the second floor", "On the third floor", "Outside the building"]'::jsonb,'On the third floor',1,31,'listening',0.55,s.id,'detail',false,st.id from public.assessment_tests t join public.assessment_sections s on s.test_id=t.id and s.code='listening' join public.assessment_stimuli st on st.code='KLI-LST-BC-01' where t.code='EN-ITP-FULL-PRACTICE';
