insert into public.assessment_stimuli(code,title,content,stimulus_type,audio_script,content_hidden,max_plays) values('KLI-LST-BC-02','Course Project Discussion','Transcript withheld during practice delivery','listening_script','Student: I have chosen a topic for my environmental science project, but it may be too broad. Professor: What are you considering? Student: Plastic pollution in the ocean. Professor: That is important, but for a ten-page report you should focus on one source or one location. Student: Could I examine plastic waste from restaurants near the harbor? Professor: Yes. Compare the waste before and after the city introduced its recycling rule. Start with municipal records, then interview two restaurant managers if time permits.',true,2) on conflict(code) do update set audio_script=excluded.audio_script,content_hidden=true,max_plays=2;
insert into public.assessment_questions(test_id,prompt,options,correct_option,points,sort_order,competency,difficulty,section_id,item_type,randomize_options,stimulus_id) select t.id,'What problem does the student have?','["The topic may be too broad", "The report is already late", "No records exist", "The professor rejected the course"]'::jsonb,'The topic may be too broad',1,35,'listening',0.55,s.id,'main_idea',false,st.id from public.assessment_tests t join public.assessment_sections s on s.test_id=t.id and s.code='listening' join public.assessment_stimuli st on st.code='KLI-LST-BC-02' where t.code='EN-ITP-FULL-PRACTICE';
insert into public.assessment_questions(test_id,prompt,options,correct_option,points,sort_order,competency,difficulty,section_id,item_type,randomize_options,stimulus_id) select t.id,'What narrower topic is selected?','["Ocean temperatures worldwide", "Restaurant plastic waste near the harbor", "Fishing laws in another country", "Household energy use"]'::jsonb,'Restaurant plastic waste near the harbor',1,36,'listening',0.55,s.id,'detail',false,st.id from public.assessment_tests t join public.assessment_sections s on s.test_id=t.id and s.code='listening' join public.assessment_stimuli st on st.code='KLI-LST-BC-02' where t.code='EN-ITP-FULL-PRACTICE';
insert into public.assessment_questions(test_id,prompt,options,correct_option,points,sort_order,competency,difficulty,section_id,item_type,randomize_options,stimulus_id) select t.id,'What comparison should the student make?','["Two different harbors", "Conditions before and after a recycling rule", "Restaurants and schools", "Paper and glass production"]'::jsonb,'Conditions before and after a recycling rule',1,37,'listening',0.55,s.id,'detail',false,st.id from public.assessment_tests t join public.assessment_sections s on s.test_id=t.id and s.code='listening' join public.assessment_stimuli st on st.code='KLI-LST-BC-02' where t.code='EN-ITP-FULL-PRACTICE';
insert into public.assessment_questions(test_id,prompt,options,correct_option,points,sort_order,competency,difficulty,section_id,item_type,randomize_options,stimulus_id) select t.id,'What should the student consult first?','["Municipal records", "Tourist photographs", "A laboratory manual", "International newspapers"]'::jsonb,'Municipal records',1,38,'listening',0.55,s.id,'sequence',false,st.id from public.assessment_tests t join public.assessment_sections s on s.test_id=t.id and s.code='listening' join public.assessment_stimuli st on st.code='KLI-LST-BC-02' where t.code='EN-ITP-FULL-PRACTICE';
insert into public.assessment_stimuli(code,title,content,stimulus_type,audio_script,content_hidden,max_plays) values('KLI-LST-BC-03','Campus Recycling Program','Transcript withheld during practice delivery','listening_script','Speaker: Last year the university replaced separate recycling bins with collection stations that use standardized colors and labels. Before the change, nearly a quarter of recyclable material was rejected because food or liquids had contaminated it. The new signs use photographs rather than long written instructions. Student volunteers observed the stations and answered questions during the first month. Contamination decreased, although it remained high in outdoor areas. The university will now add covered stations near sports fields and test clearer labels for disposable cups.',true,2) on conflict(code) do update set audio_script=excluded.audio_script,content_hidden=true,max_plays=2;
insert into public.assessment_questions(test_id,prompt,options,correct_option,points,sort_order,competency,difficulty,section_id,item_type,randomize_options,stimulus_id) select t.id,'What is the talk mainly about?','["A change to campus recycling", "A new sports competition", "Food prices on campus", "Volunteer recruitment only"]'::jsonb,'A change to campus recycling',1,39,'listening',0.55,s.id,'main_idea',false,st.id from public.assessment_tests t join public.assessment_sections s on s.test_id=t.id and s.code='listening' join public.assessment_stimuli st on st.code='KLI-LST-BC-03' where t.code='EN-ITP-FULL-PRACTICE';
insert into public.assessment_questions(test_id,prompt,options,correct_option,points,sort_order,competency,difficulty,section_id,item_type,randomize_options,stimulus_id) select t.id,'Why had recyclable material been rejected?','["It was too expensive", "It was contaminated", "It had no color", "It came from classrooms"]'::jsonb,'It was contaminated',1,40,'listening',0.55,s.id,'detail',false,st.id from public.assessment_tests t join public.assessment_sections s on s.test_id=t.id and s.code='listening' join public.assessment_stimuli st on st.code='KLI-LST-BC-03' where t.code='EN-ITP-FULL-PRACTICE';
insert into public.assessment_questions(test_id,prompt,options,correct_option,points,sort_order,competency,difficulty,section_id,item_type,randomize_options,stimulus_id) select t.id,'What did the new signs use?','["Photographs", "Long regulations", "Electronic screens", "Student names"]'::jsonb,'Photographs',1,41,'listening',0.55,s.id,'detail',false,st.id from public.assessment_tests t join public.assessment_sections s on s.test_id=t.id and s.code='listening' join public.assessment_stimuli st on st.code='KLI-LST-BC-03' where t.code='EN-ITP-FULL-PRACTICE';
insert into public.assessment_questions(test_id,prompt,options,correct_option,points,sort_order,competency,difficulty,section_id,item_type,randomize_options,stimulus_id) select t.id,'What will the university do next?','["Remove all outdoor bins", "Add covered stations near sports fields", "End the recycling program", "Prohibit disposable cups immediately"]'::jsonb,'Add covered stations near sports fields',1,42,'listening',0.55,s.id,'prediction',false,st.id from public.assessment_tests t join public.assessment_sections s on s.test_id=t.id and s.code='listening' join public.assessment_stimuli st on st.code='KLI-LST-BC-03' where t.code='EN-ITP-FULL-PRACTICE';
insert into public.assessment_stimuli(code,title,content,stimulus_type,audio_script,content_hidden,max_plays) values('KLI-LST-BC-04','Coral Reef Recovery','Transcript withheld during practice delivery','listening_script','Lecturer: Coral bleaching occurs when environmental stress causes corals to lose the algae that supply much of their energy. A bleached coral is not necessarily dead. If temperatures return to normal soon enough, algae may return and the coral can recover. Recovery depends on several factors, including the duration of heat stress, water quality, and the availability of healthy neighboring reefs. Scientists therefore monitor reefs after a bleaching event rather than estimating damage from color alone. They also measure growth, reproduction, and the return of fish communities over time.',true,2) on conflict(code) do update set audio_script=excluded.audio_script,content_hidden=true,max_plays=2;
insert into public.assessment_questions(test_id,prompt,options,correct_option,points,sort_order,competency,difficulty,section_id,item_type,randomize_options,stimulus_id) select t.id,'What causes corals to lose algae?','["Environmental stress", "Fish migration", "Normal growth", "Low sunlight alone"]'::jsonb,'Environmental stress',1,43,'listening',0.55,s.id,'detail',false,st.id from public.assessment_tests t join public.assessment_sections s on s.test_id=t.id and s.code='listening' join public.assessment_stimuli st on st.code='KLI-LST-BC-04' where t.code='EN-ITP-FULL-PRACTICE';
insert into public.assessment_questions(test_id,prompt,options,correct_option,points,sort_order,competency,difficulty,section_id,item_type,randomize_options,stimulus_id) select t.id,'What does the lecturer emphasize about bleached coral?','["It is always dead", "It may recover", "It grows faster immediately", "It no longer needs algae"]'::jsonb,'It may recover',1,44,'listening',0.55,s.id,'inference',false,st.id from public.assessment_tests t join public.assessment_sections s on s.test_id=t.id and s.code='listening' join public.assessment_stimuli st on st.code='KLI-LST-BC-04' where t.code='EN-ITP-FULL-PRACTICE';
insert into public.assessment_questions(test_id,prompt,options,correct_option,points,sort_order,competency,difficulty,section_id,item_type,randomize_options,stimulus_id) select t.id,'Which factor affects recovery?','["Building height", "Water quality", "Tourist nationality", "Ocean distance from cities only"]'::jsonb,'Water quality',1,45,'listening',0.55,s.id,'detail',false,st.id from public.assessment_tests t join public.assessment_sections s on s.test_id=t.id and s.code='listening' join public.assessment_stimuli st on st.code='KLI-LST-BC-04' where t.code='EN-ITP-FULL-PRACTICE';
insert into public.assessment_questions(test_id,prompt,options,correct_option,points,sort_order,competency,difficulty,section_id,item_type,randomize_options,stimulus_id) select t.id,'Why do scientists monitor reefs over time?','["Color alone does not show the full outcome", "They want to remove all fish", "Algae never return", "Heat stress cannot be measured"]'::jsonb,'Color alone does not show the full outcome',1,46,'listening',0.55,s.id,'purpose',false,st.id from public.assessment_tests t join public.assessment_sections s on s.test_id=t.id and s.code='listening' join public.assessment_stimuli st on st.code='KLI-LST-BC-04' where t.code='EN-ITP-FULL-PRACTICE';
insert into public.assessment_stimuli(code,title,content,stimulus_type,audio_script,content_hidden,max_plays) values('KLI-LST-BC-05','Memory and Retrieval Practice','Transcript withheld during practice delivery','listening_script','Lecturer: Students often reread a chapter because the words feel familiar. Familiarity, however, can create an illusion of mastery. Retrieval practice offers a stronger test of learning. After studying, learners close the book and try to recall the main ideas or answer questions without looking at the text. The effort involved in retrieving information strengthens later access to it. Immediate feedback is important because it corrects errors before they become established. Retrieval practice is most effective when sessions are spaced over time rather than completed in one long period.',true,2) on conflict(code) do update set audio_script=excluded.audio_script,content_hidden=true,max_plays=2;
insert into public.assessment_questions(test_id,prompt,options,correct_option,points,sort_order,competency,difficulty,section_id,item_type,randomize_options,stimulus_id) select t.id,'What problem with rereading does the lecturer identify?','["It is always too slow", "Familiarity may be mistaken for mastery", "Books become unavailable", "Students receive too much feedback"]'::jsonb,'Familiarity may be mistaken for mastery',1,47,'listening',0.55,s.id,'main_idea',false,st.id from public.assessment_tests t join public.assessment_sections s on s.test_id=t.id and s.code='listening' join public.assessment_stimuli st on st.code='KLI-LST-BC-05' where t.code='EN-ITP-FULL-PRACTICE';
insert into public.assessment_questions(test_id,prompt,options,correct_option,points,sort_order,competency,difficulty,section_id,item_type,randomize_options,stimulus_id) select t.id,'What do learners do during retrieval practice?','["Copy every sentence", "Recall information without looking", "Read continuously for hours", "Avoid answering questions"]'::jsonb,'Recall information without looking',1,48,'listening',0.55,s.id,'detail',false,st.id from public.assessment_tests t join public.assessment_sections s on s.test_id=t.id and s.code='listening' join public.assessment_stimuli st on st.code='KLI-LST-BC-05' where t.code='EN-ITP-FULL-PRACTICE';
insert into public.assessment_questions(test_id,prompt,options,correct_option,points,sort_order,competency,difficulty,section_id,item_type,randomize_options,stimulus_id) select t.id,'Why is immediate feedback useful?','["It makes sessions longer", "It corrects errors early", "It removes the need for study", "It increases familiarity only"]'::jsonb,'It corrects errors early',1,49,'listening',0.55,s.id,'purpose',false,st.id from public.assessment_tests t join public.assessment_sections s on s.test_id=t.id and s.code='listening' join public.assessment_stimuli st on st.code='KLI-LST-BC-05' where t.code='EN-ITP-FULL-PRACTICE';
insert into public.assessment_questions(test_id,prompt,options,correct_option,points,sort_order,competency,difficulty,section_id,item_type,randomize_options,stimulus_id) select t.id,'When is retrieval practice most effective?','["When sessions are spaced over time", "Only before breakfast", "In one long session", "Without any feedback"]'::jsonb,'When sessions are spaced over time',1,50,'listening',0.55,s.id,'detail',false,st.id from public.assessment_tests t join public.assessment_sections s on s.test_id=t.id and s.code='listening' join public.assessment_stimuli st on st.code='KLI-LST-BC-05' where t.code='EN-ITP-FULL-PRACTICE';
insert into public.assessment_questions(test_id,prompt,options,correct_option,points,sort_order,competency,difficulty,section_id,item_type,randomize_options,stimulus_id)
