-- Complete KLI-original Listening Comprehension practice form.
alter table public.assessment_stimuli add column if not exists audio_script text;
alter table public.assessment_stimuli add column if not exists voice_profile jsonb not null default '{"language":"en-US","rate":0.92,"pitch":1.0}'::jsonb;
alter table public.assessment_stimuli add column if not exists max_plays int not null default 2 check(max_plays between 1 and 5);
alter table public.assessment_stimuli add column if not exists content_hidden boolean not null default false;
alter table public.assessment_stimuli add column if not exists estimated_duration_seconds int;
alter table public.assessment_stimuli add column if not exists timing_map jsonb not null default '[]'::jsonb;
alter table public.assessment_attempts add column if not exists section_scores jsonb not null default '{}'::jsonb;
values('EN-ITP-FULL-PRACTICE','English','TOEFL ITP Level 1 preparation','Intermediate–Advanced','certification_readiness','KLI Institutional English Proficiency Practice Test','A complete 140-item KLI-original practice form: Listening 50, Structure and Written Expression 40, Reading 50. Not an official ETS test or score equivalent.',115,70,true,'1.0','academic_review','practice','content_ready',3,72)
on conflict(code) do update set title=excluded.title,description=excluded.description,duration_minutes=115,published=true,usage_scope='practice';
select id,'TOEFL ITP Level 1 section counts and timing; all items and scripts are KLI-original','Commercial preparation practice only','Intermediate to advanced learners','{"listening_comprehension":50,"structure_written_expression":40,"reading_comprehension":50}'::jsonb,140,false,'70% provisional practice threshold; no ETS scaled-score conversion' from public.assessment_tests where code='EN-ITP-FULL-PRACTICE'
on conflict(test_id) do update set standard_reference=excluded.standard_reference,intended_use=excluded.intended_use,skills=excluded.skills,min_objective_items=140,requires_human_rating=false;

delete from public.assessment_questions where test_id=(select id from public.assessment_tests where code='EN-ITP-FULL-PRACTICE');
select target.id,q.prompt,q.options,q.correct_option,q.points,q.sort_order+50,q.competency,q.difficulty,ts.id,q.item_type,q.randomize_options,q.stimulus_id
from public.assessment_questions q join public.assessment_tests source on source.id=q.test_id and source.code='EN-ITP-SR-DIAGNOSTIC' join public.assessment_sections ss on ss.id=q.section_id cross join public.assessment_tests target join public.assessment_sections ts on ts.test_id=target.id and ts.code=ss.code where target.code='EN-ITP-FULL-PRACTICE';
update public.assessment_stimuli set estimated_duration_seconds=greatest(3,ceil(array_length(regexp_split_to_array(trim(audio_script),'\\s+'),1)/2.3)::int),timing_map=jsonb_build_array(jsonb_build_object('start_seconds',0,'end_seconds',greatest(3,ceil(array_length(regexp_split_to_array(trim(audio_script),'\\s+'),1)/2.3)::int))) where code like 'KLI-LST-%' and audio_script is not null;
